import os,json,urllib.request
url=os.environ['GALAXY_URL']+'/api/tools/upload1/build?history_id=bbd44e69cb8906b59cfa85357171c81e'
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
obj=json.load(urllib.request.urlopen(urllib.request.Request(url,headers={'x-api-key':key})))

def walk(x,p=''):
 if isinstance(x,dict):
  nm=x.get('name'); typ=x.get('type') or x.get('model_class')
  if nm is not None: print(p, 'name=',nm,'type=',typ,'value=',repr(x.get('value'))[:300])
  for k,v in x.items():
   if k in ('options','value'): continue
   if isinstance(v,(dict,list)): walk(v,p+'/'+str(k))
 elif isinstance(x,list):
  for i,v in enumerate(x): walk(v,p+f'[{i}]')
walk(obj.get('inputs',[]))
PY"

